 64	/// This is called before any termio begins. This should not be called
 65	/// after termio begins because it may put the internal terminal state
 66	/// into a bad state.
 67	pub fn initTerminal(self: *Exec, term: *terminal.Terminal) void {
 68	    // If we have an initial pwd requested by the subprocess, then we
 69	    // set that on the terminal now. This allows rapidly initializing
 70	    // new surfaces to use the proper pwd.
 71	    if (self.subprocess.cwd) |cwd| term.setPwd(cwd) catch |err| {
 72	        log.warn("error setting initial pwd err={}", .{err});
 73	    };
